# Text for the v10 sheet update. Run: python3 v10_sheet_text.py  -> writes formula_*.txt files
import json

def q(s):
    s = s.replace('"', "'")
    parts = s.split("\n\n")
    return '&CHAR(10)&CHAR(10)&'.join('"%s"' % p for p in parts) if len(parts) > 1 else '"%s"' % s

def arr(rows):
    return "={" + ";".join(",".join(q(c) if isinstance(c, str) else str(c) for c in r) for r in rows) + "}"

